import pandas as pd

def clean(df):
    df['Quantity'] = df['Quantity'].clip(lower=0)
    df['Price'] = pd.to_numeric(df['Price'], errors='coerce').fillna(0).clip(lower=0)
    df['Region'] = df['Region'].str.upper()
    return df

def answer(df):
    category_revenue = df.groupby('Category')['Quantity'].multiply('Price').sum().reset_index()
    return {cat: total for cat, total in zip(category_revenue['Category'], category_revenue['sum'])}
